```
***
[extrait de code 2]
```java
// Correct : Utilisation sécurisée avec PreparedStatement et validation
String userInput = request.getParameter("username");
// Vérification de la longueur et nettoyage du input
if (userInput != null && userInput.length() <= 50) {
    userInput = userInput.replaceAll("[^a-zA-Z0-9]", "");
    String query = "SELECT * FROM users WHERE username = ?";
    PreparedStatement stmt = connection.prepareStatement(query);
    stmt.setString(1, userInput);
    ResultSet rs = stmt.executeQuery();
} else {
    // Gestion de l'erreur : input invalide
    System.out.println("Input invalide");
}
```

