[code snippet 2]  
```java
// अच्छा कोड: सुरक्षित इनपुट हैंडलिंग और एपीआई के अनुचित उपयोग के खिलाफ बचाव  
public class SecureExample {
    public static void main(String[] args) {
        // सुरक्षित तरीके से इनपुट के आधार पर SQL क्वेरी बनाना (उपयोग करें एपीआई जैसे JDBC)
        String userInput = "'; DROP TABLE users;--";
        String sanitizedInput = userInput.replaceAll("'", "''"); // इनपुट को स्कैन करें और बदल दें
        String query = "SELECT * FROM users WHERE username = '" + sanitizedInput + "'";
        System.out.println("Generated Query: " + query);
    }
}
```

