```java
// 易受攻击：直接使用用户输入而没有验证或过滤
public class VulnerableServlet extends HttpServlet {
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        // 获取用户输入的参数，未进行任何验证或过滤
        String userInput = request.getParameter("username");

        // 直接将用户输入写入数据库，可能导致SQL注入漏洞
        String query = "INSERT INTO users (username) VALUES ('" + userInput + "')";

        // 执行SQL查询（未使用预编译语句）
        try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydb", "user", "password");
             Statement stmt = conn.createStatement()) {
            stmt.executeUpdate(query);
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
}
***
```

[代码段2]
```java
// 修复后的代码：使用预编译语句防止SQL注入
public class SecureServlet extends HttpServlet {
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        // 获取用户输入的参数，并进行基本验证
        String userInput = request.getParameter("username");

        // 验证输入是否符合预期（例如：仅包含字母和数字）
        if (userInput != null && userInput.matches("[a-zA-Z0-9]+")) {
            // 使用预编译语句防止SQL注入
            String query = "INSERT INTO users (username) VALUES (?)";

            // 执行SQL查询（使用预编译语句）
            try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydb", "user", "password");
                 PreparedStatement pstmt = conn.prepareStatement(query)) {
                pstmt.setString(1, userInput);
                pstmt.executeUpdate();
            } catch (SQLException e) {
                e.printStackTrace();
            }
        } else {
            // 输入无效，返回错误信息
            response.getWriter().println("Invalid input.");
        }
    }
}
```

[代码片段 1]  
```java
// 易受攻击：直接使用用户输入而未进行验证或转义
public class VulnerableServlet extends HttpServlet {
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String userInput = request.getParameter("input");
        // 直接将用户输入写入响应，可能导致 XSS 漏洞
        response.getWriter().println("<html><body>");
        response.getWriter().println("你输入的内容是: " + userInput);
        response.getWriter().println("</body></html>");
    }
}
```
***
[代码片段 2]  
```java
// 安全：对用户输入进行转义，防止 XSS 漏洞
public class SecureServlet extends HttpServlet {
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String userInput = request.getParameter("input");
        // 使用 HTML 转义函数，防止恶意脚本注入
        String safeInput = org.owasp.encoder.Encode.forHtml(userInput);
        response.getWriter().println("<html><body>");
        response.getWriter().println("你输入的内容是: " + safeInput);
        response.getWriter().println("</body></html>");
    }
}
```

