// Vulnerabile: uso improprio della classe java.net.URL senza validazione degli input
public class VulnerableExample {
    public static void main(String[] args) {
        String userInput = "http://example.com"; // Input utente non validato

        try {
            // Creazione di un oggetto URL senza controlli di sicurezza
            java.net.URL url = new java.net.URL(userInput);
            java.net.HttpURLConnection connection = (java.net.HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");

            int responseCode = connection.getResponseCode();
            System.out.println("Response Code: " + responseCode);

