```java
// Corretto: validazione degli input e utilizzo sicuro delle API Java
public class SecureExample {
    public static void main(String[] args) {
        String userInput = "http://example.com"; // Input utente non validato

        // Validazione dell'input prima di usarlo
        if (isValidUrl(userInput)) {
            try {
                // Creazione di un oggetto URL dopo la validazione
                java.net.URL url = new java.net.URL(userInput);
                java.net.HttpURLConnection connection = (java.net.HttpURLConnection) url.openConnection();
                connection.setRequestMethod("GET");

                int responseCode = connection.getResponseCode();
                System.out.println("Response Code: " + responseCode);

            } catch (Exception e) {
                e.printStackTrace();
            }
        } else {
            System.out.println("URL non valido o non sicuro.");
        }
    }

    // Metodo per validare l'URL
    private static boolean isValidUrl(String url) {
        try {
            new java.net.URL(url).toURI();
            return true;
        } catch (Exception e) {
            return false;
        }
    }
}
```

